        actual_classes[hostname].append(actual_class)


fig = go.Figure()

for hostname in predicted_classes.keys():
    fig.add_trace(go.Scatter(
        x=np.arange(len(actual_classes[hostname])),
        y=actual_classes[hostname],
        mode='lines+markers',
        name=f'Actual Class {hostname}'
    ))

    fig.add_trace(go.Scatter(
        x=np.arange(len(predicted_classes[hostname])),
        y=predicted_classes[hostname],
        mode='lines+markers',
        name=f'Predicted Class {hostname}'
    ))

fig.update_layout(
    title='Comparison of Actual and Predicted Classes by Hostname',
    xaxis_title='Data Index',
    yaxis_title='Class',
    xaxis=dict(rangeslider=dict(visible=True))
)

